style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://scontent-dfw5-2.xx.fbcdn.net/v/t1.15752-9/494356926_1068983021758827_7492171097603894594_n.jpg?stp=dst-jpg_p480x480_tt6&_nc_cat=100&ccb=1-7&_nc_sid=0024fc&_nc_ohc=DAy4MiPhbUwQ7kNvwE3qHtu&_nc_oc=Adm0WV0FLFft-7634LR0RonbaxgN8LV8l9bxTBnWozQWcToqPIpviz1Q_M02JqWNYgA&_nc_ad=z-m&_nc_cid=0&_nc_zt=23&_nc_ht=scontent-dfw5-2.xx&oh=03_Q7cD2QH7Jc1sQw_CVma4peJeDoInf1P-DWaDN4UXzLwzrKlFPA&oe=68462948") no-repeat center center fixed !important;
        background-size: cover !important;
        color: white !important;
    }

    .theme-base, .container, .header, .footer, .content, .game-card-container {
        background-color: rgba(0, 0, 0, 0.8) !important;
        color: white !important;
    }

    a, .text-label, .game-card-name, .game-card-creator {
        color: #ccc !important;
    }

    ::-webkit-scrollbar {
        width: 8px;
    }

    ::-webkit-scrollbar-track {
        background: #000;
    }

    ::-webkit-scrollbar-thumb {
        background: #444;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #888;
    }
}
